+                return s + '.';
+            })
+            .ToList();
+    }
+
+    private static Dictionary<string, int> BuildWordFrequencies(List<string> sentences)
+    {
+        var freq = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
+        foreach (var sentence in sentences)
+        {
+            foreach (var word in Tokenize(sentence))
+            {
+                freq.TryGetValue(word, out int count);
+                freq[word] = count + 1;
+            }
+        }
+        return freq;
+    }
+
+    private static List<(int Index, double Score)> ScoreSentences(
+        List<string> sentences, Dictionary<string, int> wordFrequencies)
+    {
+        return sentences.Select((sentence, index) =>
+        {
+            var words = Tokenize(sentence);
+            double score = words.Length == 0
+                ? 0
+                : words.Sum(w => wordFrequencies.GetValueOrDefault(w, 0)) / (double)words.Length;
+            return (Index: index, Score: score);
+        }).ToList();
+    }
+
+    private static string[] Tokenize(string text)
+    {
+        return text
+            .Split([' ', ',', ';', ':', '"', '\'', '(', ')', '[', ']', '\n', '\r', '\t'],
+                   StringSplitOptions.RemoveEmptyEntries)
+            .Select(w => w.Trim('.', '!', '?').ToLowerInvariant())
+            .Where(w => w.Length > 2)
+            .ToArray();
+    }
+}
